import { useState } from "react";
import type { LoaderFunctionArgs } from "react-router";
import { useLoaderData } from "react-router";
import { authenticate } from "../shopify.server";
import db from "../db.server";
import { getPlan } from "../lib/plans";

// ---------------------------------------------------------------------------
// Helpers
// ---------------------------------------------------------------------------

function formatDate(date: string | Date): string {
  const d = typeof date === "string" ? new Date(date) : date;
  return d.toLocaleDateString("en-US", {
    month: "short",
    day: "numeric",
    year: "numeric",
  });
}

// ---------------------------------------------------------------------------
// Loader
// ---------------------------------------------------------------------------

export const loader = async ({ request }: LoaderFunctionArgs) => {
  const { session } = await authenticate.admin(request);
  const shop = session.shop;

  const thirtyDaysAgo = new Date(Date.now() - 30 * 24 * 60 * 60 * 1000);

  const [
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    subscription,
    recentCharts,
    widgetConfig,
    recommenderConfig,
    assignmentCount,
  ] = await Promise.all([
    db.sizeChart.count({ where: { shop } }),
    db.sizeChart.count({ where: { shop, status: "active" } }),
    db.sizeChart.count({ where: { shop, status: "draft" } }),
    db.analyticsEvent.count({
      where: { shop, eventType: "view", createdAt: { gte: thirtyDaysAgo } },
    }),
    db.analyticsEvent.count({ where: { shop, eventType: "recommend" } }),
    db.subscription.findUnique({ where: { shop } }),
    db.sizeChart.findMany({
      where: { shop },
      orderBy: { updatedAt: "desc" },
      take: 5,
      select: {
        id: true,
        name: true,
        category: true,
        status: true,
        updatedAt: true,
        _count: { select: { assignments: true } },
      },
    }),
    db.widgetConfig.findUnique({ where: { shop } }),
    db.recommenderConfig.findUnique({ where: { shop } }),
    db.chartAssignment.count({ where: { shop } }),
  ]);

  const plan = getPlan(subscription?.planId ?? "free");

  const hasChart = chartCount > 0;
  const hasAssignment = assignmentCount > 0;
  const hasWidget = widgetConfig !== null;
  const hasRecommender =
    recommenderConfig !== null && recommenderConfig.enabled;

  const setupSteps = [
    {
      key: "create-chart",
      title: "Create your first size chart",
      description:
        "Choose from 9 ready-made templates or build a custom chart from scratch.",
      done: hasChart,
      actionLabel: "Create chart",
      actionUrl: "/app/size-charts",
    },
    {
      key: "customize-widget",
      title: "Style your size chart widget",
      description:
        "Customize colors, layout, and text to match your store's brand.",
      done: hasWidget,
      actionLabel: "Go to Appearance",
      actionUrl: "/app/widget",
    },
    {
      key: "assign-products",
      title: "Assign chart to products",
      description:
        "Link your chart to products, collections, or tags so it shows automatically.",
      done: hasAssignment,
      actionLabel: "Assign products",
      actionUrl: "/app/size-charts",
    },
  ];

  const completedCount = setupSteps.filter((s) => s.done).length;

  return {
    shop,
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts: recentCharts.map((c) => ({
      ...c,
      assignmentCount: c._count.assignments,
      updatedAt: c.updatedAt.toISOString(),
    })),
    hasRecommender,
    setupSteps,
    completedCount,
    totalSteps: setupSteps.length,
  };
};

// ---------------------------------------------------------------------------
// Component
// ---------------------------------------------------------------------------

export default function Dashboard() {
  const {
    chartCount,
    activeChartCount,
    draftChartCount,
    monthlyViews,
    totalRecommendations,
    plan,
    recentCharts,
    setupSteps,
    completedCount,
    totalSteps,
  } = useLoaderData<typeof loader>();

  const [setupOpen, setSetupOpen] = useState(true);
  const [expandedStep, setExpandedStep] = useState<string | null>(
    setupSteps.find((s) => !s.done)?.key ?? null,
  );

  const isSetupComplete = completedCount === totalSteps;
  const isFreePlan = plan.id === "free";
  const maxCharts = plan.limits.maxCharts;

  const progressPct = Math.round((completedCount / totalSteps) * 100);
  const chartUsagePct = maxCharts > 0
    ? Math.min(100, Math.round((chartCount / maxCharts) * 100))
    : 0;

  return (
    <s-page heading="Dashboard">
      {/* Primary action */}
      <s-button slot="primary-action" variant="primary" href="/app/size-charts">
        Create Size Chart
      </s-button>

      {/* ================================================================ */}
      {/* SETUP GUIDE                                                       */}
      {/* ================================================================ */}
      {!isSetupComplete && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              {/* Header */}
              <s-stack direction="inline" gap="base">
                <s-stack direction="block" gap="small-200" style={{ flex: 1 }}>
                  <s-heading>Setup guide</s-heading>
                  <s-text tone="neutral">
                    Use this personalized guide to get started with Size Chart &amp; Recommender.
                  </s-text>
                </s-stack>
                <s-button onClick={() => setSetupOpen(!setupOpen)}>
                  {setupOpen ? "Hide" : "Show"}
                </s-button>
              </s-stack>

              {/* Progress */}
              <s-text tone="neutral">
                {completedCount} of {totalSteps} steps completed
              </s-text>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${progressPct}%`,
                    background: "#1a73e8",
                    borderRadius: "3px",
                    transition: "width 0.3s ease",
                  }}
                />
              </div>

              {/* Steps */}
              {setupOpen && (
                <s-stack direction="block" gap="small-200">
                  {setupSteps.map((step) => (
                    <s-box
                      key={step.key}
                      padding="base"
                      borderWidth="base"
                      borderRadius="base"
                      onClick={() =>
                        setExpandedStep(
                          expandedStep === step.key ? null : step.key,
                        )
                      }
                      style={{ cursor: "pointer" }}
                    >
                      <s-stack direction="block" gap="small-200">
                        <s-stack direction="inline" gap="small-200">
                          {step.done ? (
                            <s-badge tone="success">Done</s-badge>
                          ) : (
                            <s-badge>To do</s-badge>
                          )}
                          <s-text>{step.title}</s-text>
                        </s-stack>
                        {expandedStep === step.key && !step.done && (
                          <s-stack direction="block" gap="small-200">
                            <s-text tone="neutral">{step.description}</s-text>
                            <s-button variant="primary" href={step.actionUrl}>
                              {step.actionLabel}
                            </s-button>
                          </s-stack>
                        )}
                      </s-stack>
                    </s-box>
                  ))}
                </s-stack>
              )}
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* STATS OVERVIEW                                                    */}
      {/* ================================================================ */}
      <s-section>
        <div style={{ display: "flex", gap: "16px", flexWrap: "wrap" }}>
          <s-box
            padding="base"
            borderWidth="base"
            borderRadius="base"
            style={{ flex: "1 1 0", minWidth: "140px", textAlign: "center" }}
          >
            <s-stack direction="block" gap="small-200">
              <s-heading>{chartCount}</s-heading>
              <s-text>Total charts</s-text>
              <s-text tone="neutral">
                {activeChartCount} active · {draftChartCount} draft
              </s-text>
            </s-stack>
          </s-box>

          <s-box
            padding="base"
            borderWidth="base"
            borderRadius="base"
            style={{ flex: "1 1 0", minWidth: "140px", textAlign: "center" }}
          >
            <s-stack direction="block" gap="small-200">
              <s-heading>{activeChartCount}</s-heading>
              <s-text>Published charts</s-text>
              <s-text tone="neutral">Visible on storefront</s-text>
            </s-stack>
          </s-box>

          <s-box
            padding="base"
            borderWidth="base"
            borderRadius="base"
            style={{ flex: "1 1 0", minWidth: "140px", textAlign: "center" }}
          >
            <s-stack direction="block" gap="small-200">
              <s-heading>{monthlyViews}x</s-heading>
              <s-text>Views — current month</s-text>
              <s-text tone="neutral">Last 30 days</s-text>
            </s-stack>
          </s-box>

          <s-box
            padding="base"
            borderWidth="base"
            borderRadius="base"
            style={{ flex: "1 1 0", minWidth: "140px", textAlign: "center" }}
          >
            <s-stack direction="block" gap="small-200">
              <s-heading>{totalRecommendations}</s-heading>
              <s-text>AI recommendations</s-text>
              <s-text tone="neutral">
                {plan.limits.aiRecommender ? "Active" : "Upgrade to unlock"}
              </s-text>
            </s-stack>
          </s-box>
        </div>
      </s-section>

      {/* ================================================================ */}
      {/* CTA BANNER — no charts yet                                        */}
      {/* ================================================================ */}
      {chartCount === 0 && (
        <s-section>
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-heading>Show size charts for all your products</s-heading>
              <s-text tone="neutral">
                Help your customers easily find the right size for every
                product. Reduce returns by up to 40%.
              </s-text>
              <s-stack direction="inline" gap="small-200">
                <s-button variant="primary" href="/app/size-charts">
                  Create chart
                </s-button>
                <s-button href="/app/pricing">View plans</s-button>
              </s-stack>
            </s-stack>
          </s-box>
        </s-section>
      )}

      {/* ================================================================ */}
      {/* RECENT SIZE CHARTS                                                */}
      {/* ================================================================ */}
      <s-section
        heading={chartCount > 0 ? "Recent size charts" : "Create your size chart"}
      >
        {recentCharts.length === 0 ? (
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <s-stack direction="block" gap="small-200">
              <s-text tone="neutral">
                Create various types of size charts, AI Size Recommendations.
              </s-text>
              <s-button variant="primary" href="/app/size-charts">
                Create a Size Chart
              </s-button>
            </s-stack>
          </s-box>
        ) : (
          <s-stack direction="block" gap="small-200">
            {recentCharts.map((chart) => (
              <s-box
                key={chart.id}
                padding="base"
                borderWidth="base"
                borderRadius="base"
              >
                <div
                  style={{
                    display: "flex",
                    justifyContent: "space-between",
                    alignItems: "center",
                  }}
                >
                  <s-stack direction="block" gap="small-200">
                    <s-link href={`/app/size-charts/${chart.id}`}>
                      {chart.name}
                    </s-link>
                    <s-stack direction="inline" gap="small-200">
                      <s-badge>{chart.category}</s-badge>
                      <s-badge
                        tone={chart.status === "active" ? "success" : "neutral"}
                      >
                        {chart.status === "active" ? "Active" : "Draft"}
                      </s-badge>
                      <s-text tone="neutral">
                        {chart.assignmentCount > 0
                          ? `${chart.assignmentCount} product${chart.assignmentCount > 1 ? "s" : ""}`
                          : "No assignments"}
                      </s-text>
                    </s-stack>
                  </s-stack>
                  <s-text tone="neutral">{formatDate(chart.updatedAt)}</s-text>
                </div>
              </s-box>
            ))}
            <s-link href="/app/size-charts">View all</s-link>
          </s-stack>
        )}
      </s-section>

      {/* ================================================================ */}
      {/* ENABLE APP                                                        */}
      {/* ================================================================ */}
      <s-section heading="Enable app">
        <s-text tone="neutral">
          Keep the app active to display size charts on your store.
        </s-text>
        <s-stack direction="block" gap="small-200">
          <s-box padding="base" borderWidth="base" borderRadius="base">
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <s-stack direction="inline" gap="small-200">
                <s-text>Theme App Extension</s-text>
                <s-badge tone="info">Required</s-badge>
              </s-stack>
              <s-badge tone={activeChartCount > 0 ? "success" : "neutral"}>
                {activeChartCount > 0 ? "Active" : "Inactive"}
              </s-badge>
            </div>
          </s-box>

          <s-box padding="base" borderWidth="base" borderRadius="base">
            <div
              style={{
                display: "flex",
                justifyContent: "space-between",
                alignItems: "center",
              }}
            >
              <s-stack direction="inline" gap="small-200">
                <s-text>App Block</s-text>
                <s-badge tone="neutral">Optional</s-badge>
              </s-stack>
              <s-badge tone={activeChartCount > 0 ? "success" : "neutral"}>
                {activeChartCount > 0 ? "Active" : "Inactive"}
              </s-badge>
            </div>
          </s-box>
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Plan & Usage                                              */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Your plan">
        <s-stack direction="block" gap="base">
          <s-stack direction="inline" gap="small-200">
            <s-badge tone={isFreePlan ? "neutral" : "success"}>
              {plan.name}
            </s-badge>
            <s-text tone="neutral">
              {plan.price === 0 ? "Free" : `$${plan.price}/mo`}
            </s-text>
          </s-stack>

          {isFreePlan && maxCharts > 0 && (
            <s-stack direction="block" gap="small-200">
              <s-text tone="neutral">
                {chartCount} / {maxCharts} charts used
              </s-text>
              <div
                style={{
                  height: "6px",
                  background: "#e4e5e7",
                  borderRadius: "3px",
                  overflow: "hidden",
                }}
              >
                <div
                  style={{
                    height: "100%",
                    width: `${chartUsagePct}%`,
                    background: chartCount >= maxCharts ? "#d72c0d" : "#1a73e8",
                    borderRadius: "3px",
                  }}
                />
              </div>
            </s-stack>
          )}

          <s-unordered-list>
            {plan.features.slice(0, 4).map((f, i) => (
              <s-list-item key={i}>{f}</s-list-item>
            ))}
          </s-unordered-list>

          {isFreePlan && (
            <s-button href="/app/pricing" variant="primary">
              Upgrade plan
            </s-button>
          )}
        </s-stack>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Quick links                                               */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Quick links">
        <s-unordered-list>
          <s-list-item>
            <s-link href="/app/size-charts">Size Charts</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/widget">Widget Appearance</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/recommender">AI Recommender</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/analytics">Analytics</s-link>
          </s-list-item>
          <s-list-item>
            <s-link href="/app/settings">Settings</s-link>
          </s-list-item>
        </s-unordered-list>
      </s-section>

      {/* ================================================================ */}
      {/* ASIDE — Help & Resources                                          */}
      {/* ================================================================ */}
      <s-section slot="aside" heading="Need help?">
        <s-stack direction="block" gap="base">
          <s-text tone="neutral">We respond within 2 hours.</s-text>
          <s-unordered-list>
            <s-list-item>
              <s-link href="mailto:support@sizechart.app">Email support</s-link>
            </s-list-item>
            <s-list-item>
              <s-link href="/app/settings">App settings</s-link>
            </s-list-item>
          </s-unordered-list>
          {plan.limits.prioritySupport && (
            <s-badge tone="success">Priority support</s-badge>
          )}
        </s-stack>
      </s-section>
    </s-page>
  );
}

